import struct
import hashlib
import hmac
import os
import socket
import threading
from typing import Optional, Tuple

SERVER_SECRET = os.environ.get('SERVER_SECRET', '').encode()
if not SERVER_SECRET:
    raise RuntimeError("SERVER_SECRET must be set")

MAX_MESSAGE_SIZE = 65536
HEADER_FORMAT = '!4sIBH'  # magic(4) + payload_length(unsigned int) + flags(uint8) + version(uint16)
HEADER_SIZE = struct.calcsize(HEADER_FORMAT)
MAGIC = b'XMSG'

def compute_mac(data: bytes) -> bytes:
    return hmac.new(SERVER_SECRET, data, hashlib.sha256).digest()

def verify_mac(data: bytes, mac: bytes) -> bool:
    expected = hmac.new(SERVER_SECRET, data, hashlib.sha256).digest()
    return hmac.compare_digest(expected, mac)

class MessageBuffer:
    """Ring buffer for message assembly from stream data."""

    def __init__(self, capacity: int = 131072):
        self._buf = bytearray(capacity)
        self._capacity = capacity
        self._write_pos = 0
        self._read_pos = 0

    def available(self) -> int:
        return (self._write_pos - self._read_pos) % self._capacity

    def write(self, data: bytes) -> int:
        space = self._capacity - self.available() - 1
        to_write = min(len(data), space)
        for i in range(to_write):
            self._buf[self._write_pos % self._capacity] = data[i]
            self._write_pos = (self._write_pos + 1) % self._capacity
        return to_write

    def read(self, count: int) -> bytes:
        available = self.available()
        to_read = min(count, available)
        result = bytearray(to_read)
        for i in range(to_read):
            result[i] = self._buf[self._read_pos % self._capacity]
            self._read_pos = (self._read_pos + 1) % self._capacity
        return bytes(result)

    def peek(self, count: int) -> bytes:
        available = self.available()
        to_read = min(count, available)
        result = bytearray(to_read)
        pos = self._read_pos
        for i in range(to_read):
            result[i] = self._buf[pos % self._capacity]
            pos = (pos + 1) % self._capacity
        return bytes(result)


def parse_header(data: bytes) -> Optional[Tuple[bytes, int, int, int]]:
    """Parse message header, returns (magic, length, flags, version) or None."""
    if len(data) < HEADER_SIZE:
        return None
    magic, length, flags, version = struct.unpack(HEADER_FORMAT, data[:HEADER_SIZE])
    if magic != MAGIC:
        return None
    return (magic, length, flags, version)


def validate_message_length(length: int) -> bool:
    """Validate that message length is within acceptable bounds.

    Length field represents payload size. We check it doesn't exceed
    our maximum to prevent resource exhaustion.
    """
    # With unsigned int format ('I'), length is always >= 0
    if length > MAX_MESSAGE_SIZE:
        return False
    return True


def extract_payload(buffer: MessageBuffer) -> Optional[bytes]:
    """Extract a complete message payload from the buffer.

    Returns the payload bytes if a complete message is available,
    None otherwise.
    """
    if buffer.available() < HEADER_SIZE:
        return None

    header_data = buffer.peek(HEADER_SIZE)
    parsed = parse_header(header_data)
    if parsed is None:
        # Invalid header, skip one byte to resync
        buffer.read(1)
        return None

    magic, payload_length, flags, version = parsed

    if not validate_message_length(payload_length):
        # Invalid length, skip header to resync
        buffer.read(HEADER_SIZE)
        return None

    # Total message size: header + payload + MAC (32 bytes)
    total_size = HEADER_SIZE + payload_length + 32

    if buffer.available() < total_size:
        # Message not yet complete
        return None

    # Consume the header
    buffer.read(HEADER_SIZE)

    # Read payload
    payload = buffer.read(payload_length)

    # Read and verify MAC
    mac = buffer.read(32)
    mac_input = header_data + payload

    if not verify_mac(mac_input, mac):
        return None

    return payload


class SecureMessageServer:
    """TCP server that processes length-prefixed authenticated messages."""

    def __init__(self, host: str = '127.0.0.1', port: int = 9999):
        self._host = host
        self._port = port
        self._running = False
        self._connections = []
        self._lock = threading.Lock()

    def start(self):
        self._running = True
        self._socket = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        self._socket.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
        self._socket.bind((self._host, self._port))
        self._socket.listen(5)
        self._socket.settimeout(1.0)

        while self._running:
            try:
                conn, addr = self._socket.accept()
                t = threading.Thread(target=self._handle_client, args=(conn, addr))
                t.daemon = True
                t.start()
            except socket.timeout:
                continue

    def stop(self):
        self._running = False

    def _handle_client(self, conn: socket.socket, addr):
        buffer = MessageBuffer()
        conn.settimeout(30.0)

        try:
            while self._running:
                try:
                    data = conn.recv(4096)
                    if not data:
                        break
                    buffer.write(data)

                    # Process all complete messages
                    while True:
                        payload = extract_payload(buffer)
                        if payload is None:
                            break
                        response = self._process_payload(payload)
                        if response:
                            conn.sendall(response)
                except socket.timeout:
                    continue
        finally:
            conn.close()

    def _process_payload(self, payload: bytes) -> Optional[bytes]:
        """Process a verified payload and return response."""
        if len(payload) == 0:
            # Heartbeat - respond with empty payload
            return self._build_response(b'')

        # Echo back the payload (application logic would go here)
        return self._build_response(payload)

    def _build_response(self, payload: bytes) -> bytes:
        """Build a response message with header and MAC."""
        header = struct.pack(HEADER_FORMAT, MAGIC, len(payload), 0, 1)
        mac_input = header + payload
        mac = compute_mac(mac_input)
        return header + payload + mac


if __name__ == '__main__':
    server = SecureMessageServer()
    try:
        server.start()
    except KeyboardInterrupt:
        server.stop()
